<template>
  <view class="sm-card"><text class="sm-h2">引用统计 · {{ period.start_date }} 至 {{ period.end_date }}</text><text v-if="statistics.as_of_date" class="sm-help">统计截止日：{{ statistics.as_of_date }}。历史待办按该日状态列示，当前状态另列。</text><view class="sm-grid sm-grid--three sm-stat-grid"><view v-for="stat in stats" :key="stat.key"><text class="sm-muted">{{ stat.label }}</text><text class="sm-stat">{{ statistics[stat.key] ?? '待核对' }}</text></view><view><text class="sm-muted">整改完成率</text><text class="sm-stat">{{ statistics.rectification_rate_label || '待核对' }}</text></view></view><text class="sm-help">新增按首次发现日期和唯一隐患编号计算；完成数仅计已复查销号。复见、复发及历史待办单列。</text><view class="sm-row"><text class="sm-tag">复见 {{ statistics.reobservations?.length ?? '待核对' }}</text><text class="sm-tag">复发 {{ statistics.recurrence?.length ?? '待核对' }}</text><text class="sm-tag">历史待办 {{ statistics.historical_pending?.length ?? '待核对' }}</text></view><view v-if="Array.isArray(statistics.weekly_reports)" class="sm-field"><text class="sm-h3">本月关联周排查报告 · {{ statistics.weekly_reports.length }} 份</text><text class="sm-help">列出统计周期与本月重叠的已保存周报告；跨月周仍保留完整统计范围，不重复相加隐患数。</text><view v-for="weekly in statistics.weekly_reports" :key="weekly._id" class="sm-list-row"><view class="sm-section-head"><text class="sm-h3">{{ weekly.period?.start_date }} 至 {{ weekly.period?.end_date }}</text><text class="sm-link" @click="openSafetyPage('weekly',{date:weekly.period?.start_date})">查看周报告</text></view><text class="sm-text">实际排查：{{ weekly.content?.actual_date || '待填写' }} · 组织人：{{ weekly.content?.organizer || '待填写' }}</text><text class="sm-help">保存版本 {{ weekly.revision }} · {{ weekly.content_status==='complete'?'内容完整':'草稿 / 待完善' }} · 待签认</text></view><text v-if="!statistics.weekly_reports.length" class="sm-help">本月尚无关联周报告记录；不能据此认定已开展周排查。</text></view><view class="sm-expand sm-link" @click="expanded=!expanded">{{ expanded?'收起':'查看' }}日表来源与隐患明细 {{ expanded?'−':'+' }}</view><template v-if="expanded"><view class="sm-row"><text v-for="day in statistics.daily" :key="day.date" class="sm-tag sm-link" @click="openSafetyPage('daily',{date:day.date})">{{ day.date }} · {{ dayLabel(day.status) }}</text></view><view v-for="group in hazardGroups" :key="group.key" class="sm-list-row"><text class="sm-h3">{{ group.label }}</text><view v-for="(issue,index) in statistics[group.key] || []" :key="issue._id || index" class="sm-list-row"><text class="sm-text">{{ issue.hazard_no || issue.hazard_id || issue._id }} · {{ issue.issue_note || issue.note || '' }}</text><text class="sm-help">{{ issue.responsible_name || '' }} {{ issue.planned_complete_date || '' }}</text><text v-if="issue.status" class="sm-help">{{ issue.as_of_date ? `截至 ${issue.as_of_date}` : '记录状态' }}：{{ hazardStatus(issue.status) }}<template v-if="issue.current_status"> · 当前：{{ hazardStatus(issue.current_status) }}</template><template v-if="issue.closure_time_unverified"> · 关闭时间证据待核验</template></text></view><text v-if="!statistics[group.key]?.length" class="sm-help">无此类记录</text></view></template></view>
</template>
<script setup>
import { ref } from 'vue'
import { openSafetyPage } from './helpers'
defineProps({statistics:{type:Object,default:()=>({})},period:{type:Object,default:()=>({})}})
const expanded=ref(false)
const stats=[{key:'expected_days',label:'应检天数'},{key:'inspected_days',label:'实际巡检天数'},{key:'checked_days',label:'日表内容核对天数'},{key:'new_hazard_count',label:'本期新发现隐患'},{key:'verified_closed_count',label:'本期新增中已复查销号'}]
const hazardGroups=[{key:'new_hazards',label:'本期新发现'},{key:'reobservations',label:'本期复见观察'},{key:'recurrence',label:'关闭后复发'},{key:'historical_pending',label:'历史待办'},{key:'historical_progress',label:'历史问题本期处置与销号'}]
function hazardStatus(value){return({pending_rectification:'待整改',pending_verification:'待复查',closed:'已复查销号',cancelled:'已取消'})[value] || value}
function dayLabel(value){return({no_inspection:'无巡检',incomplete:'日表待完成',pending_signature:'待签认',recheck_required:'待重新核对',not_enabled:'未启用'})[value] || '待核对'}
</script>
<style scoped>.sm-stat-grid { margin:22rpx 0; }</style>
